# PLATFORM GATE (T#0088): actual CPU topology must match build\PLATFORM.json.
# Baseline is generated by the reproducible command in PLATFORM.json's _generated_by
# field -- never hand-written. Fail-closed: missing baseline = no build.
param([string]$Log = "")
$ErrorActionPreference = 'Stop'
$base = Join-Path $PSScriptRoot 'PLATFORM.json'
function Log-Line([string]$s) { if ($Log) { Add-Content -LiteralPath $Log -Value ("[gate:platform] " + $s) } }
$cs = Get-CimInstance Win32_ComputerSystem
$cp = Get-CimInstance Win32_Processor | Select-Object -First 1
$actualCpu = $cp.Name.Trim()
$actualPhys = [int]$cp.NumberOfCores
$actualLogi = [int]$cs.NumberOfLogicalProcessors
if (-not (Test-Path -LiteralPath $base)) {
    Write-Output 'PLATFORM-BASELINE-MISSING'
    Log-Line 'PLATFORM-BASELINE-MISSING (fail-closed, build refused)'
    exit 1
}
$bj = Get-Content -LiteralPath $base -Raw -Encoding UTF8 | ConvertFrom-Json
$diff = @()
if ($actualCpu -ne [string]$bj.cpu) { $diff += ("cpu: base=" + $bj.cpu + " actual=" + $actualCpu) }
if ([int]$bj.physical_cores -ne $actualPhys) { $diff += ("physical_cores: base=" + $bj.physical_cores + " actual=" + $actualPhys) }
if ([int]$bj.logical_processors -ne $actualLogi) { $diff += ("logical_processors: base=" + $bj.logical_processors + " actual=" + $actualLogi) }
if ($diff.Count -gt 0) {
    Write-Output 'PLATFORM-CHANGED'
    $diff | ForEach-Object { Write-Output ("  " + $_) }
    Log-Line ('PLATFORM-CHANGED: ' + ($diff -join '; '))
    exit 1
}
Write-Output 'PLATFORM-OK'
Log-Line 'PLATFORM-OK'
exit 0
